INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_GERMANIC_SAGA','Germanic Heroic-Legendary Cycle (Matter of the North)',500,1300)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BYOCK_VOLSUNGS','primary text','Byock, Jesse L. (trans.), The Saga of the Volsungs: The Norse Epic of Sigurd the Dragon Slayer (Penguin Classics)','Germanic Legend — the Volsung/Nibelung heroic cycle: Sigurd, the Volsungs, Fafnir, Brynhild, the Gjukungs, Andvari''s cursed gold')
INSERT INTO _e VALUES
 ('ENT_GSAGA_VOLSUNG_CYCLE','Volsung Cycle (Matter of the North)','collective','cycle','Germanic Legend','heroic-legendary cycle','B','Organizing hub for the Volsung/Nibelung legendary cycle, attested across Volsunga saga, the Poetic Edda heroic lays, and the Nibelungenlied.'),
 ('ENT_GSAGA_SIGURD','Sigurd','hero','hero','Germanic Legend','dragon-slaying, heroism','B','The dragon-slayer (Old High German Siegfried), central hero of Volsunga saga who slays Fafnir and wins the cursed Andvari hoard; son of Sigmund. Sigurðr Fáfnisbani = Nibelungenlied''s Siegfried.'),
 ('ENT_GSAGA_BRYNHILD','Brynhild','heroine','heroine','Germanic Legend','valkyrie, vengeance','B','Shieldmaiden/valkyrie betrothed to Sigurd; her betrayal via the Gjukungs drives the tragedy. Nibelungenlied''s Brünhild.'),
 ('ENT_GSAGA_FAFNIR','Fafnir','monster','dragon','Germanic Legend','dragon, cursed hoard','B','Dwarf-turned-dragon who guards the cursed gold of Andvari; slain by Sigurd. Brother of Reginn.'),
 ('ENT_GSAGA_REGINN','Reginn','hero','smith','Germanic Legend','smithing, fosterage, treachery','B','Smith and foster-father of Sigurd who reforges the sword Gram and incites the slaying of his brother Fafnir; later slain by Sigurd.'),
 ('ENT_GSAGA_SIGMUND','Sigmund','hero','hero','Germanic Legend','heroism, Volsung line','B','Son of Volsung, wielder of the sword drawn from Barnstokkr; father of Sigurd. Twin of Signy.'),
 ('ENT_GSAGA_SIGNY','Signy','heroine','heroine','Germanic Legend','vengeance, kin-tragedy','B','Daughter of Volsung, twin of Sigmund; engineers vengeance against Siggeir for the slaughter of her kin.'),
 ('ENT_GSAGA_VOLSUNG','Volsung','hero','hero','Germanic Legend','dynastic ancestor','B','Eponymous king and ancestor of the Volsung line, descendant of Odin; father of Sigmund and Signy.'),
 ('ENT_GSAGA_GUNNAR','Gunnar','hero','hero','Germanic Legend','kingship, oath-treachery','B','Gjukung king, brother of Gudrun, who wins Brynhild through deceit and conspires in Sigurd''s death. Nibelungenlied''s Gunther.'),
 ('ENT_GSAGA_GUDRUN','Gudrun','heroine','heroine','Germanic Legend','grief, vengeance','B','Gjukung princess, wife of Sigurd; her grief and revenge drive the cycle''s later tragedies. Nibelungenlied''s Kriemhild.'),
 ('ENT_GSAGA_HOGNI','Hogni','hero','hero','Germanic Legend','warrior, kin-loyalty','B','Gjukung brother of Gunnar and Gudrun, party to Sigurd''s killing; dies defiantly in the hall of Atli. Nibelungenlied''s Hagen.'),
 ('ENT_GSAGA_VOLUNDR','Volundr (Wayland the Smith)','hero','smith','Germanic Legend','smithing, captivity, revenge','B','Legendary master smith (Old English Weland, German Wieland); his captivity and vengeance are told in the eddic Volundarkvida and Old English Deor/Franks Casket. Volundr = Old English Weland/Wayland = German Wieland; cross-attested beyond Byock in the Poetic Edda.'),
 ('ENT_GSAGA_STARKADR','Starkadr','hero','hero','Germanic Legend','warrior, fate, Odinic favor','C','Multi-generational warrior-hero blessed and cursed by the gods; prominent in Saxo''s Gesta Danorum and Gautreks saga.'),
 ('ENT_GSAGA_HERVOR','Hervor','heroine','heroine','Germanic Legend','shieldmaiden, cursed sword','C','Shieldmaiden who claims the cursed sword Tyrfing from her father''s barrow; central to Hervarar saga.'),
 ('ENT_GSAGA_RAGNARR','Ragnarr Lodbrok','hero','hero','Germanic Legend','viking kingship, legend','C','Legendary Viking king and serpent-slayer; subject of Ragnars saga lodbrokar, loosely linked to the Volsung material through his wife Aslaug, daughter of Sigurd and Brynhild.');
