INSERT INTO _p VALUES
 ('ENT_GSAGA_VOLSUNG_CYCLE','PER_GERMANIC_SAGA','Organizing hub for the Volsung/Nibelung legendary cycle, attested across Volsunga saga, the Poetic Edda heroic lays, and the Nibelungenlied.'),
 ('ENT_GSAGA_SIGURD','PER_GERMANIC_SAGA','The dragon-slayer (Old High German Siegfried), central hero of Volsunga saga who slays Fafnir and wins the cursed Andvari hoard; son of Sigmund. Sigurðr Fáfnisbani = Nibelungenlied''s Siegfried.'),
 ('ENT_GSAGA_BRYNHILD','PER_GERMANIC_SAGA','Shieldmaiden/valkyrie betrothed to Sigurd; her betrayal via the Gjukungs drives the tragedy. Nibelungenlied''s Brünhild.'),
 ('ENT_GSAGA_FAFNIR','PER_GERMANIC_SAGA','Dwarf-turned-dragon who guards the cursed gold of Andvari; slain by Sigurd. Brother of Reginn.'),
 ('ENT_GSAGA_REGINN','PER_GERMANIC_SAGA','Smith and foster-father of Sigurd who reforges the sword Gram and incites the slaying of his brother Fafnir; later slain by Sigurd.'),
 ('ENT_GSAGA_SIGMUND','PER_GERMANIC_SAGA','Son of Volsung, wielder of the sword drawn from Barnstokkr; father of Sigurd. Twin of Signy.'),
 ('ENT_GSAGA_SIGNY','PER_GERMANIC_SAGA','Daughter of Volsung, twin of Sigmund; engineers vengeance against Siggeir for the slaughter of her kin.'),
 ('ENT_GSAGA_VOLSUNG','PER_GERMANIC_SAGA','Eponymous king and ancestor of the Volsung line, descendant of Odin; father of Sigmund and Signy.'),
 ('ENT_GSAGA_GUNNAR','PER_GERMANIC_SAGA','Gjukung king, brother of Gudrun, who wins Brynhild through deceit and conspires in Sigurd''s death. Nibelungenlied''s Gunther.'),
 ('ENT_GSAGA_GUDRUN','PER_GERMANIC_SAGA','Gjukung princess, wife of Sigurd; her grief and revenge drive the cycle''s later tragedies. Nibelungenlied''s Kriemhild.'),
 ('ENT_GSAGA_HOGNI','PER_GERMANIC_SAGA','Gjukung brother of Gunnar and Gudrun, party to Sigurd''s killing; dies defiantly in the hall of Atli. Nibelungenlied''s Hagen.'),
 ('ENT_GSAGA_VOLUNDR','PER_GERMANIC_SAGA','Legendary master smith (Old English Weland, German Wieland); his captivity and vengeance are told in the eddic Volundarkvida and Old English Deor/Franks Casket. Volundr = Old English Weland/Wayland = German Wieland; cross-attested beyond Byock in the Poetic Edda.'),
 ('ENT_GSAGA_STARKADR','PER_GERMANIC_SAGA','Multi-generational warrior-hero blessed and cursed by the gods; prominent in Saxo''s Gesta Danorum and Gautreks saga.'),
 ('ENT_GSAGA_HERVOR','PER_GERMANIC_SAGA','Shieldmaiden who claims the cursed sword Tyrfing from her father''s barrow; central to Hervarar saga.'),
 ('ENT_GSAGA_RAGNARR','PER_GERMANIC_SAGA','Legendary Viking king and serpent-slayer; subject of Ragnars saga lodbrokar, loosely linked to the Volsung material through his wife Aslaug, daughter of Sigurd and Brynhild.');
