INSERT INTO _r VALUES
 ('ENT_GSAGA_SIGURD','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Sigurd is the central hero of the Volsung cycle (Byock, Saga of the Volsungs).'),
 ('ENT_GSAGA_BRYNHILD','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Brynhild is a principal figure of the cycle.'),
 ('ENT_GSAGA_FAFNIR','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Fafnir the dragon is integral to the Sigurd legend.'),
 ('ENT_GSAGA_REGINN','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Reginn the smith fosters Sigurd within the cycle.'),
 ('ENT_GSAGA_SIGMUND','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Sigmund is a Volsung hero and Sigurd''s father.'),
 ('ENT_GSAGA_SIGNY','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Signy is a Volsung in the early saga.'),
 ('ENT_GSAGA_VOLSUNG','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Volsung is the eponymous dynastic ancestor of the cycle.'),
 ('ENT_GSAGA_GUNNAR','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Gunnar is a Gjukung within the cycle.'),
 ('ENT_GSAGA_GUDRUN','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Gudrun is Sigurd''s wife and a Gjukung within the cycle.'),
 ('ENT_GSAGA_HOGNI','member_of','ENT_GSAGA_VOLSUNG_CYCLE','high','Hogni is a Gjukung within the cycle.'),
 ('ENT_GSAGA_VOLUNDR','member_of','ENT_GSAGA_VOLSUNG_CYCLE','medium','Wayland the Smith belongs to the broader Germanic heroic-legendary corpus.'),
 ('ENT_GSAGA_STARKADR','member_of','ENT_GSAGA_VOLSUNG_CYCLE','medium','Starkadr is part of the wider Germanic legendary tradition (Saxo/Gautreks saga).'),
 ('ENT_GSAGA_HERVOR','member_of','ENT_GSAGA_VOLSUNG_CYCLE','medium','Hervor belongs to the wider Germanic heroic-legendary corpus (Hervarar saga).'),
 ('ENT_GSAGA_RAGNARR','member_of','ENT_GSAGA_VOLSUNG_CYCLE','medium','Ragnarr''s saga is tied to the Volsung line via his wife Aslaug, daughter of Sigurd and Brynhild.'),
 ('ENT_GSAGA_SIGURD','slays','ENT_GSAGA_FAFNIR','high','Sigurd slays Fafnir with the sword Gram, the cycle''s defining deed.'),
 ('ENT_GSAGA_FAFNIR','slain_by','ENT_GSAGA_SIGURD','high','Fafnir is killed by Sigurd.'),
 ('ENT_GSAGA_SIGURD','slays','ENT_GSAGA_REGINN','high','Sigurd kills the treacherous Reginn after roasting Fafnir''s heart.'),
 ('ENT_GSAGA_SIGURD','consort_of','ENT_GSAGA_BRYNHILD','high','Sigurd is betrothed to Brynhild before being deceived into marrying Gudrun.'),
 ('ENT_GSAGA_BRYNHILD','consort_of','ENT_GSAGA_SIGURD','high','Brynhild is Sigurd''s beloved/betrothed.'),
 ('ENT_GSAGA_SIGURD','consort_of','ENT_GSAGA_GUDRUN','high','Sigurd marries Gudrun under the spell of forgetfulness.'),
 ('ENT_GSAGA_GUDRUN','consort_of','ENT_GSAGA_SIGURD','high','Gudrun is Sigurd''s wife.'),
 ('ENT_GSAGA_BRYNHILD','consort_of','ENT_GSAGA_GUNNAR','high','Brynhild is married to Gunnar after he wins her by Sigurd''s disguised aid.'),
 ('ENT_GSAGA_GUNNAR','consort_of','ENT_GSAGA_BRYNHILD','high','Gunnar weds Brynhild.'),
 ('ENT_GSAGA_SIGURD','child_of','ENT_GSAGA_SIGMUND','high','Sigurd is the posthumous son of Sigmund.'),
 ('ENT_GSAGA_SIGMUND','parent_of','ENT_GSAGA_SIGURD','high','Sigmund fathers Sigurd.'),
 ('ENT_GSAGA_SIGMUND','child_of','ENT_GSAGA_VOLSUNG','high','Sigmund is the son of King Volsung.'),
 ('ENT_GSAGA_VOLSUNG','parent_of','ENT_GSAGA_SIGMUND','high','Volsung fathers Sigmund.'),
 ('ENT_GSAGA_SIGNY','child_of','ENT_GSAGA_VOLSUNG','high','Signy is the daughter of King Volsung.'),
 ('ENT_GSAGA_VOLSUNG','parent_of','ENT_GSAGA_SIGNY','high','Volsung fathers Signy.'),
 ('ENT_GSAGA_SIGMUND','sibling_of','ENT_GSAGA_SIGNY','high','Sigmund and Signy are twins.'),
 ('ENT_GSAGA_SIGNY','sibling_of','ENT_GSAGA_SIGMUND','high','Signy and Sigmund are twins.'),
 ('ENT_GSAGA_FAFNIR','sibling_of','ENT_GSAGA_REGINN','high','Fafnir and Reginn are brothers, sons of Hreidmar.'),
 ('ENT_GSAGA_REGINN','sibling_of','ENT_GSAGA_FAFNIR','high','Reginn and Fafnir are brothers.'),
 ('ENT_GSAGA_GUNNAR','sibling_of','ENT_GSAGA_GUDRUN','high','Gunnar and Gudrun are siblings among the Gjukungs.'),
 ('ENT_GSAGA_GUDRUN','sibling_of','ENT_GSAGA_GUNNAR','high','Gudrun and Gunnar are siblings.'),
 ('ENT_GSAGA_GUNNAR','sibling_of','ENT_GSAGA_HOGNI','high','Gunnar and Hogni are Gjukung brothers.'),
 ('ENT_GSAGA_HOGNI','sibling_of','ENT_GSAGA_GUNNAR','high','Hogni and Gunnar are brothers.'),
 ('ENT_GSAGA_GUNNAR','opposes','ENT_GSAGA_SIGURD','high','Gunnar and the Gjukungs conspire in Sigurd''s murder.'),
 ('ENT_GSAGA_REGINN','opposes','ENT_GSAGA_FAFNIR','high','Reginn incites the killing of his brother Fafnir to seize the hoard.'),
 ('ENT_GSAGA_REGINN','associated_with','ENT_NOR_ANDVARI','high','Reginn and Fafnir''s family seizes Andvari''s cursed gold and ring, the hoard Sigurd later wins (Byock, Saga of the Volsungs).'),
 ('ENT_GSAGA_FAFNIR','guardian_of','ENT_NOR_ANDVARI','medium','Fafnir broods on Glittering Heath over the cursed hoard originally extorted from the dwarf Andvari.'),
 ('ENT_GSAGA_SIGURD','associated_with','ENT_NOR_ANDVARI','high','By slaying Fafnir, Sigurd wins Andvari''s cursed gold and ring Andvaranaut, transmitting the curse through the cycle.'),
 ('ENT_GSAGA_VOLSUNG_CYCLE','reception_of','ENT_NOR_ODIN','high','Odin appears throughout the Volsung legend (planting the sword in Barnstokkr, advising Sigurd, claiming the slain), linking the literary cycle to the Norse divine cosmos.'),
 ('ENT_GSAGA_VOLSUNG','child_of','ENT_NOR_ODIN','medium','The Volsung line is descended from Odin via Sigi in the saga''s genealogy (Byock).'),
 ('ENT_NOR_ODIN','parent_of','ENT_GSAGA_VOLSUNG','medium','Odin is the divine ancestor of the Volsung dynasty.'),
 ('ENT_GSAGA_STARKADR','patronized_by','ENT_NOR_ODIN','medium','Starkadr is granted long life and martial prowess by Odin (and cursed by Thor), per Gautreks saga.'),
 ('ENT_GSAGA_BRYNHILD','associated_with','ENT_NOR_ODIN','medium','As a valkyrie Brynhild is one of Odin''s shieldmaidens, put to sleep by him for disobedience.'),
 ('ENT_GSAGA_SIGURD','aligned_with','ENT_NOR_TYR','low','Sigurd''s dragon-slaying heroism is sometimes compared to the war-god Tyr''s combat against Fenrir as parallel Germanic monster-fights; loose thematic alignment, not identity.');
